import { Context } from "effect";
import { MediaClient } from "./media-client.js";
export class SpeechClientService extends Context.Service()("@opencode/SpeechClient") {
}
export const Service = SpeechClientService;
export const SpeechClient = {
    Service,
    ...MediaClient.make(Service, {
        modality: "speech",
        responseEvents: (response) => [
            ...(response.timestamps === undefined ? [] : [{ type: "timestamps", items: response.timestamps }]),
            {
                type: "finish",
                audio: response.audio,
                usage: response.usage,
                providerMetadata: response.providerMetadata,
            },
        ],
    }),
};
